function atualizarNavegacaoInferiorFarol(idTela){

    const barra =
        document.getElementById("barraInferiorFarol");

    if(!barra){
        return;
    }

    const telasSemBarra = [
        "login",
        "cadastro",
        "confirmacaoAdminFarol"
    ];

    barra.classList.toggle(
        "barra-inferior-oculta",
        telasSemBarra.includes(idTela)
    );

    let itemAtivo = idTela;

    const telasDoEstudo = [
        "questoes",
        "historia",
        "ciencias",
        "geografia",
        "portugues",
        "informatica",
        "didatica",
        "etica",
        "apoioEscolar",
        "teoria",
        "telaMapaMental",
        "resolverQuestao",
        "telaBNCC",
        "forum"
    ];

    if(telasDoEstudo.includes(idTela)){
        itemAtivo = "questoes";
    }

    if(idTela === "duelos"){
        itemAtivo = "duelos";
    }

    barra.querySelectorAll(".item-barra-inferior").forEach(botao => {
        botao.classList.toggle(
            "ativo",
            botao.dataset.telaApp === itemAtivo
        );
    });
}

function abrirAbaInicioFarol(nomeAba, opcoes = {}){

    const abaPermitida = [
        "resumo",
        "progresso",
        "ranking",
        "online"
    ].includes(nomeAba)
        ? nomeAba
        : "resumo";

    const telaInicio =
        document.getElementById("inicio");

    if(!telaInicio){
        return;
    }

    if(!telaInicio.classList.contains("ativa")){
        document.querySelectorAll(".tela").forEach(tela => {
            tela.classList.remove("ativa");
        });

        telaInicio.classList.add("ativa");

        localStorage.setItem(
            "farol_telaAtual",
            "inicio"
        );
    }

    telaInicio.querySelectorAll(".painel-inicio-bloco").forEach(bloco => {
        bloco.classList.remove("painel-inicio-visivel");
    });

    const destino =
        telaInicio.querySelector(
            ".painel-inicio-" + abaPermitida
        );

    if(destino){
        destino.classList.add("painel-inicio-visivel");
    }

    telaInicio.querySelectorAll(".aba-inicio-farol").forEach(botao => {
        botao.classList.toggle(
            "ativa",
            botao.dataset.abaInicio === abaPermitida
        );
    });

    const barra =
        document.getElementById("barraInferiorFarol");

    if(barra){
        barra.querySelectorAll(".item-barra-inferior").forEach(botao => {
            const ativo =
                abaPermitida === "ranking"
                ? botao.dataset.telaApp === "ranking"
                : botao.dataset.telaApp === "inicio";

            botao.classList.toggle("ativo", ativo);
        });
    }

    sessionStorage.setItem(
        "farol_abaInicioAtual",
        abaPermitida
    );

    if(!opcoes.semHistorico){
        registrarEstadoNavegacaoFarol(
            "inicio",
            abaPermitida
        );
    }

    window.scrollTo({
        top: 0,
        left: 0,
        behavior: "smooth"
    });
}

document.addEventListener("DOMContentLoaded", function(){

    abrirAbaInicioFarol("resumo", { semHistorico: true });

    const telaAtual =
        localStorage.getItem("farol_telaAtual") ||
        "inicio";

    atualizarNavegacaoInferiorFarol(telaAtual);

    registrarEstadoNavegacaoFarol(
        "inicio",
        "resumo",
        true
    );
});

window.addEventListener("popstate", function(event){

    const estado =
        event.state && event.state.farol
        ? event.state
        : null;

    if(!estado){
        return;
    }

    navegandoPeloHistoricoFarol = true;

    try{
        if(estado.tela === "inicio"){
            abrirAbaInicioFarol(
                estado.abaInicio || "resumo",
                { semHistorico: true }
            );
        }else{
            mostrarTela(
                estado.tela,
                { semHistorico: true }
            );
        }
    }finally{
        setTimeout(() => {
            navegandoPeloHistoricoFarol = false;
        }, 0);
    }
});


function nomeDisciplinaForum(chave){

    const nomes = {
        portugues: "Língua Portuguesa",
        informatica: "Informática",
        ciencias: "Professor de Ciências",
        didatica: "Didática e Legislação",
        historia: "História",
        etica: "Ética no Serviço Público",
        apoioEscolar: "Apoio Escolar",
        administrador: "Administrador"
    };

    return nomes[chave] || "Disciplina";

}

function atualizarTituloForum(){

    const area =
        document.getElementById("tituloForumDisciplina");

    if(!area){
        return;
    }

    area.innerHTML =
        "Discussão da disciplina: <strong>" +
        nomeDisciplinaForum(disciplinaForumAtual) +
        "</strong>";

}

function abrirForum(disciplina){

    disciplinaForumAtual = disciplina;

    localStorage.setItem(
        "farol_disciplinaForum",
        disciplina
    );

    telaOrigemForum =
        localStorage.getItem("farol_telaAtual")
        || "";

    mostrarTela("forum");

    setTimeout(() => {
        atualizarTituloForum();
        renderizarForum();
        atualizarContadorForum();
    }, 0);

}


async function novaPergunta(){

    const pergunta = prompt(
        "Digite sua dúvida:"
    );

    if(
        !pergunta ||
        pergunta.trim() === ""
    ){
        return;
    }

    const agora = new Date();

    const dataHora =
        agora.toLocaleString();

const novaPerguntaObj = {

    id: Date.now(),

    disciplina:
        disciplinaForumAtual,

    autor:
        usuarioForum,

    autorEmail:
        usuarioEmail,

    avatarAtual:
        lojaFarol.avatarAtual || "👤",

    nomeAvatarAtual:
        lojaFarol.nomeAvatarAtual || "Estudante",

    pergunta:
        pergunta.trim(),

    data:
        dataHora,

    respostas: []

};

await db
.collection("forumGlobal")
.add(novaPerguntaObj);

atualizarContadorForum();

}

async function responderPergunta(firebaseId){

    const resposta = prompt(
        "Digite sua resposta:"
    );

    if(
        !resposta ||
        resposta.trim() === ""
    ){
        return;
    }

    const perguntaEncontrada =
    perguntasForum.find(

        p => p.firebaseId === firebaseId

    );

    if(!perguntaEncontrada){
        mostrarToast("Pergunta não encontrada.");
        return;
    }

    const novasRespostas = [

        ...(perguntaEncontrada.respostas || []),

        {
            autor: usuarioForum,
            autorEmail: usuarioEmail,
            avatarAtual: lojaFarol.avatarAtual || "👤",
            nomeAvatarAtual: lojaFarol.nomeAvatarAtual || "Estudante",
            data: new Date().toLocaleString(),
            texto: resposta.trim(),
            curtidas: 0,
            curtidoPor: []
        }

    ];

    try{

    await db
    .collection("forumGlobal")
    .doc(firebaseId)
    .update({

        respostas: novasRespostas

    });

    
}catch(erro){

    console.error(erro);

    alert(
        "ERRO: " + erro.message
    );

}

}

function renderizarForum(){

    const listaForum =
    document.getElementById(
        "listaForum"
    );

    if(!listaForum){
        return;
    }

    const perguntasDaDisciplina =
        [...perguntasForum]
        .filter(item =>
            item.disciplina === disciplinaForumAtual
        )
        .sort((a,b) => a.id - b.id);

    if(perguntasDaDisciplina.length === 0){

        listaForum.innerHTML =
        `
            <div class="forum-vazio">
                <strong>💬 Nenhuma pergunta cadastrada nesta disciplina.</strong>
                <p>Seja o primeiro aluno a abrir uma discussão.</p>
            </div>
        `;

        atualizarContadorForum();
        return;

    }

    listaForum.innerHTML = "";

    perguntasDaDisciplina.forEach(item => {

        const avatarPergunta =
            item.avatarAtual || "👤";

        const nomePerguntaRaw =
            item.autor || "Aluno";

        const nomePergunta =
            escaparHTML(nomePerguntaRaw);

        const dataPergunta =
            escaparHTML(item.data || "");

        const textoPergunta =
            escaparHTML(item.pergunta || "");

        listaForum.innerHTML += `

        <div class="card-forum card-forum-avatar">

            <div class="cabecalho-forum-avatar">

                <div class="avatar-forum-msg">
                    ${montarAvatarHTML(
                        avatarPergunta,
                        item.nomeAvatarAtual || "Avatar",
                        "avatar-forum-img"
                    )}
                </div>

                <div class="dados-forum-msg">

                    <div class="autor-forum">
                        ${nomePergunta}
                    </div>

                    <div class="data-forum">
                        📅 ${dataPergunta}
                    </div>

                </div>

            </div>

            <div class="pergunta-forum-texto">
                ❓ ${textoPergunta}
            </div>

<div class="botoes-forum">

<button
    class="btn-responder"
    onclick="responderPergunta('${item.firebaseId}')">

    💬 Responder

</button>

${
    item.autor === usuarioForum
    ||
    ehAdmin()
    ?
    `
    <button
        class="btn-excluir"
        onclick="excluirPergunta('${item.firebaseId}')">

        🗑 Excluir

    </button>
    `
    :
    ""
}

</div>

<div class="respostas respostas-com-avatar">

${
    (item.respostas || [])

    .map((resposta, indice) => {

        const avatarResposta =
            resposta.avatarAtual || "👤";

        const nomeRespostaRaw =
            resposta.autor || "Aluno";

        const nomeResposta =
            escaparHTML(nomeRespostaRaw);

        const dataResposta =
            escaparHTML(resposta.data || "");

        const textoResposta =
            escaparHTML(resposta.texto || "");

        return `

    <div class="resposta-forum resposta-forum-avatar">

        <div class="cabecalho-resposta-avatar">

            <div class="avatar-forum-msg avatar-resposta-msg">
                ${montarAvatarHTML(
                    avatarResposta,
                    resposta.nomeAvatarAtual || "Avatar",
                    "avatar-forum-img avatar-resposta-img"
                )}
            </div>

            <div class="dados-forum-msg">

                <div class="autor-forum">
                    ${nomeResposta}
                </div>

                <div class="data-forum">
                    📅 ${dataResposta}
                </div>

            </div>

        </div>

        <div class="texto-resposta-forum">
            💬 ${textoResposta}
        </div>

<div class="botoes-resposta">

<button
    onclick="curtirResposta(
        '${item.firebaseId}',
        ${indice}
    )">

👍 ${resposta.curtidas || 0}

</button>

${
    resposta.autor === usuarioForum
    ||
    ehAdmin()
    ?
    `
    <button
        class="btn-excluir"
        onclick="excluirResposta(
            '${item.firebaseId}',
            ${indice}
        )">

        🗑 Excluir

    </button>
    `
    :
    ""
}

</div>

    </div>

    `;

    })
.join("")
}

</div>

        </div>

        <br>

        `;

    });

    atualizarContadorForum();

}



function carregarForum(){

    db.collection("forumGlobal")

    .onSnapshot(snapshot => {

        perguntasForum = [];

        snapshot.forEach(doc => {

            perguntasForum.push({

                firebaseId: doc.id,

                ...doc.data()

            });

        });

        renderizarForum();

    });

}

async function excluirPergunta(firebaseId){

    const confirmar = confirm(
        "Deseja excluir esta pergunta?"
    );

    if(!confirmar){
        return;
    }

    await db
    .collection("forumGlobal")
    .doc(firebaseId)
    .delete();

}

async function excluirResposta(
    firebaseId,
    indiceResposta
){

    const confirmar = confirm(
        "Deseja excluir esta resposta?"
    );

    if(!confirmar){
        return;
    }

    try {

        const pergunta =
        perguntasForum.find(

            p => p.firebaseId === firebaseId

        );

        if(!pergunta){
            mostrarToast("Pergunta não encontrada");
            return;
        }

        const respostas = [

            ...(pergunta.respostas || [])

        ];

        respostas.splice(
            indiceResposta,
            1
        );

        await db
        .collection("forumGlobal")
        .doc(firebaseId)
        .update({

            respostas: respostas

        });

        mostrarToast("Resposta excluída com sucesso");

    } catch(error){

        console.error(error);

        mostrarToast(
            "ERRO: " +
            error.message
        );

    }

}


async function curtirResposta(
    firebaseId,
    indiceResposta
){

    const pergunta =
    perguntasForum.find(

        p => p.firebaseId === firebaseId

    );

    if(!pergunta){
        return;
    }

    const respostas = [

        ...(pergunta.respostas || [])

    ];

    const resposta =
    respostas[indiceResposta];

    if(!resposta){
        return;
    }

    if(!resposta.curtidoPor){

        resposta.curtidoPor = [];

    }

    if(

        resposta.curtidoPor.includes(
            usuarioForum
        )

    ){

        mostrarToast(
            "Você já curtiu esta resposta."
        );

        return;

    }

    resposta.curtidas =
        (resposta.curtidas || 0) + 1;

    resposta.curtidoPor.push(
        usuarioForum
    );

    await db
    .collection("forumGlobal")
    .doc(firebaseId)
    .update({

        respostas: respostas

    });

}

function voltarForum(){

    const destino =
        telaOrigemForum
        || disciplinaForumAtual
        || "questoes";

    mostrarTela(destino);

}

