// ==========================
// CADERNO DE ERROS
// ==========================

function obterStatusCadernoErro(item){

    if(
        item.status === "corrigida" ||
        item.status === "recuperada"
    ){
        return "recuperada";
    }

    if(item.status === "recuperacao"){
        return "revisao";
    }

    return "pendente";

}

function obterRotuloStatusCaderno(item){

    const status =
        obterStatusCadernoErro(item);

    if(status === "recuperada"){
        return "✅ Recuperada";
    }

    if(status === "revisao"){
        return "🔁 Em revisão";
    }

    return "❌ Pendente";

}

function definirFiltroCadernoErros(filtro){

    localStorage.setItem(
        "farol_filtro_caderno_erros",
        filtro
    );

    atualizarCadernoErros();

}

function contarCadernoErrosPorStatus(){

    const resumo = {
        total: cadernoErros.length,
        pendentes: 0,
        revisao: 0,
        recuperadas: 0,
        revisaveis: 0,
        pontosPossiveis: 0
    };

    cadernoErros.forEach(item => {

        const status =
            obterStatusCadernoErro(item);

        if(status === "pendente"){
            resumo.pendentes++;
        }
        else if(status === "revisao"){
            resumo.revisao++;
        }
        else if(status === "recuperada"){
            resumo.recuperadas++;
        }

        if(
            status !== "recuperada" &&
            Array.isArray(item.alternativas)
        ){
            resumo.revisaveis++;
        }

        if(
            status !== "recuperada" &&
            !item.pontosRevisaoGanhos
        ){
            resumo.pontosPossiveis += 5;
        }

    });

    return resumo;

}

function montarBotaoFiltroCaderno(filtroAtual, filtro, texto, quantidade){

    return `
        <button
            class="btn-filtro-caderno ${filtroAtual === filtro ? "ativo" : ""}"
            onclick="definirFiltroCadernoErros('${filtro}')">

            ${texto}
            <span>${quantidade}</span>

        </button>
    `;

}

function atualizarResumoCadernoErros(){

    const painel =
        document.getElementById(
            "painelResumoCadernoErros"
        );

    const filtros =
        document.getElementById(
            "filtrosCadernoErros"
        );

    if(!painel || !filtros){
        return;
    }

    const resumo =
        contarCadernoErrosPorStatus();

    const filtroAtual =
        localStorage.getItem(
            "farol_filtro_caderno_erros"
        ) || "todos";

    painel.innerHTML = `
        <div class="resumo-caderno-card">
            <span>❌</span>
            <strong>${resumo.pendentes}</strong>
            <small>Pendentes</small>
        </div>

        <div class="resumo-caderno-card">
            <span>🔁</span>
            <strong>${resumo.revisao}</strong>
            <small>Em revisão</small>
        </div>

        <div class="resumo-caderno-card">
            <span>✅</span>
            <strong>${resumo.recuperadas}</strong>
            <small>Recuperadas</small>
        </div>

        <div class="resumo-caderno-card">
            <span>⭐</span>
            <strong>${resumo.pontosPossiveis}</strong>
            <small>Pontos possíveis</small>
        </div>
    `;

    filtros.innerHTML =
        montarBotaoFiltroCaderno(
            filtroAtual,
            "todos",
            "Todos",
            resumo.total
        ) +
        montarBotaoFiltroCaderno(
            filtroAtual,
            "pendentes",
            "Pendentes",
            resumo.pendentes
        ) +
        montarBotaoFiltroCaderno(
            filtroAtual,
            "revisao",
            "Em revisão",
            resumo.revisao
        ) +
        montarBotaoFiltroCaderno(
            filtroAtual,
            "recuperadas",
            "Recuperadas",
            resumo.recuperadas
        );

}

function atualizarCadernoErros() {

    const lista =
        document.getElementById("listaErros");

    if(!lista){
        return;
    }

    atualizarResumoCadernoErros();

    if (cadernoErros.length === 0) {

        lista.innerHTML = `
            <div class="card caderno-vazio">
                <h3>✅ Nenhum erro registrado.</h3>
                <br>
                <p>
                    Continue estudando. Quando errar uma questão, ela aparecerá aqui
                    para revisão inteligente.
                </p>
            </div>
        `;

        return;
    }

    const filtroAtual =
        localStorage.getItem(
            "farol_filtro_caderno_erros"
        ) || "todos";

    const ordenado =
        [...cadernoErros].sort(
            (a,b) => (b.data || 0) - (a.data || 0)
        );

    const filtrado =
        ordenado.filter(item => {

            const status =
                obterStatusCadernoErro(item);

            if(filtroAtual === "todos"){
                return true;
            }

            if(filtroAtual === "pendentes"){
                return status === "pendente";
            }

            if(filtroAtual === "revisao"){
                return status === "revisao";
            }

            if(filtroAtual === "recuperadas"){
                return status === "recuperada";
            }

            return true;

        });

    if(filtrado.length === 0){

        lista.innerHTML = `
            <div class="card caderno-vazio">
                <h3>🔎 Nenhum item neste filtro.</h3>
                <br>
                <p>
                    Escolha outro filtro ou continue estudando para alimentar seu Caderno de Erros.
                </p>
            </div>
        `;

        return;

    }

    lista.innerHTML = `

    <div class="card caderno-acoes">
        <h3>🧠 Revisão Inteligente</h3>
        <p>
            Revise seus erros por prioridade. Cada primeira revisão correta rende
            <strong>5 Pontos de Luz</strong>. Quando acertar novamente, a questão será
            marcada como recuperada.
        </p>
        <br>
        <button onclick="revisarProximoErroCaderno()">
            🚀 Revisar próximo erro
        </button>
    </div>

    ` + filtrado.map(item => {

        const indiceOriginal =
            cadernoErros.indexOf(item);

        const podeRevisar =
            Array.isArray(item.alternativas) &&
            obterStatusCadernoErro(item) !== "recuperada";

        const status =
            obterStatusCadernoErro(item);

        const classeStatus =
            status === "recuperada"
            ? "status-recuperada"
            : status === "revisao"
            ? "status-revisao"
            : "status-pendente";

        return `

    <div class="card card-erro-inteligente ${classeStatus}">

        <div class="cabecalho-card-erro">

            <div>
                <h3>
                    ${obterRotuloStatusCaderno(item)}
                </h3>

                <small>
                    📚 ${item.disciplina || "-"}
                </small>
            </div>

            <span class="badge-erros">
                ${item.erros || 1} erro(s)
            </span>

        </div>

        <br>

        <div class="info-revisao-card">
            <span>
                🔁 Acertos em revisão:
                <strong>${item.acertosRevisao || 0}/2</strong>
            </span>

            <span>
                ⭐ Recompensa:
                <strong>
                    ${
                        item.pontosRevisaoGanhos
                        ? "já recebida"
                        : "5 Pontos de Luz"
                    }
                </strong>
            </span>
        </div>

        <br>

        <strong>📌 Pergunta:</strong>
        <p class="pergunta-caderno">
            ${item.pergunta || "-"}
        </p>

        <br>

        <details>
            <summary>✅ Ver resposta correta</summary>
            <br>
            ${item.respostaCorreta || "-"}
        </details>

        <br>

        <details>
            <summary>📚 Ver explicação e dica</summary>
            <br>
            ${item.explicacao || item.feedbackErro || "Sem explicação cadastrada."}
            <br><br>
            <strong>💡 Dica da banca:</strong>
            <br>
            ${item.dicaBanca || "Sem dica cadastrada."}
        </details>

        <br>

        <div class="acoes-card-erro">

            ${podeRevisar ? `
                <button onclick="revisarErro(${indiceOriginal})">
                    🔁 Revisar agora
                </button>
            ` : status === "recuperada" ? `
                <button
                    class="btn-caderno-secundario"
                    onclick="removerErroCaderno(${indiceOriginal})">

                    🗑 Remover

                </button>
            ` : `
                <p class="aviso-caderno-antigo">
                    Esta questão foi registrada antes da atualização do Caderno Inteligente.
                    Erre novamente a questão no modo normal para habilitar revisão com alternativas.
                </p>
            `}

        </div>

    </div>

    `}).join("");
}

// ==========================
// RESETAR PROGRESSO
// ==========================

function resetarProgresso() {

    const confirmar = confirm(
        "Deseja apagar todo o progresso?"
    );

    if (!confirmar) {
        return;
    }

    localStorage.clear();

    acertos = 0;
    erros = 0;
    cadernoErros = [];
    progressoAssuntos = {};

    atualizarEstatisticas();
    atualizarDashboard();
    atualizarPainelEstudos();
    atualizarCadernoErros();

    mostrarToast("Progresso apagado com sucesso!");

}

// ==========================
// SIMULADOS v0.6
// ==========================

function iniciarSimulado(qtd) {

revisaoSimuladoRespondidoFarol = null;

tipoSimuladoAtual = "geral";

const todasQuestoes = Object.values(
    bancoQuestoes
).flat();

    questoesSimulado =
        [...todasQuestoes]
        .sort(() => Math.random() - 0.5)
        .slice(0, qtd);

    modoSimulado = true;

    indiceSimulado = 0;

    acertosSimulado = 0;

    errosSimulado = 0;

    mostrarQuestaoSimulado();

}

// ==========================
// SAIR DO SIMULADO
// ==========================

function voltarDaQuestaoSimuladoFarol(){

    const respondidas =
        acertosSimulado + errosSimulado;

    const mensagem =
        respondidas > 0
        ? "Deseja sair do simulado? O progresso desta tentativa será perdido."
        : "Deseja voltar para a tela anterior?";

    if(!confirm(mensagem)){
        return;
    }

    revisaoSimuladoRespondidoFarol = null;

    modoSimulado = false;
    questoesSimulado = [];
    indiceSimulado = 0;
    acertosSimulado = 0;
    errosSimulado = 0;
    respostasSimulado = [];

    const destino =
        telaOrigemSimuladoFarol &&
        telaOrigemSimuladoFarol !== "resolverQuestao"
        ? telaOrigemSimuladoFarol
        : "simulados";

    mostrarTela(destino);
}


// ==========================
// MOSTRAR QUESTÃO SIMULADO
// ==========================

function mostrarQuestaoSimulado() {

    revisaoSimuladoRespondidoFarol = null;

    if(
        indiceSimulado === 0 &&
        acertosSimulado === 0 &&
        errosSimulado === 0
    ){
        respostasSimulado = [];
    }

    const area =
        document.getElementById("areaQuestao");

    const q =
        questoesSimulado[indiceSimulado];

    const percentual =
        Math.round(
            ((indiceSimulado + 1) /
            questoesSimulado.length) * 100
        );

    const telaAtualAntesDoSimulado =
        localStorage.getItem("farol_telaAtual") || "";

    if(
        telaAtualAntesDoSimulado &&
        telaAtualAntesDoSimulado !== "resolverQuestao"
    ){
        telaOrigemSimuladoFarol = telaAtualAntesDoSimulado;
    }

    mostrarTela("resolverQuestao");

    area.innerHTML = `

    <div class="card card-questao-foco-v29">

        <div class="cabecalho-questao-foco-v29">
            <span>Questão ${indiceSimulado + 1} de ${questoesSimulado.length}</span>
            <strong>${percentual}%</strong>
        </div>

        <progress
            class="progresso-questao-foco-v29"
            value="${indiceSimulado + 1}"
            max="${questoesSimulado.length}">
        </progress>

        <div id="inicioQuestaoFarol" class="inicio-questao-farol-v29">

${q.texto ? `

<div class="card texto-base">

    <h3>
        📄 Texto de Apoio
    </h3>

    <br>

    <p>
        ${q.texto}
    </p>

</div>

<br>

` : ""}

${q.imagem ? `
<img
    src="${q.imagem}"
    class="imagem-questao"
    loading="lazy"
    decoding="async"
    onerror="this.style.display='none'; this.insertAdjacentHTML('afterend', '<div class=&quot;aviso-farol aviso-farol-compacto&quot;><strong>⚠️ Imagem não encontrada.</strong><span>Verifique o caminho da imagem no banco de questões.</span></div>');">
<br><br>
` : ""}

${q.afirmacoes ? `

<div class="card texto-base">

${q.afirmacoes.map(item => `
<p>${item}</p>
`).join("")}

</div>

<br>

` : ""}

        <p class="pergunta">

            ${q.pergunta}

        </p>

        ${q.alternativas.map((alt, index) => `

            <label class="alternativa">

                <input
                    type="radio"
                    name="resposta"
                    value="${index}">

                ${alt}

            </label>

        `).join("")}

        <br>

        <div class="acoes-simulado-v48">
            <button
                type="button"
                class="btn-voltar-simulado-v48"
                onclick="voltarDaQuestaoSimuladoFarol()">
                ← Voltar
            </button>

            <button
                type="button"
                class="btn-responder-simulado-v48"
                onclick="corrigirSimulado()">
                Responder
            </button>
        </div>

        <div id="feedback"></div>

        </div>
    </div>

    `;

    requestAnimationFrame(() => {
        const inicio = document.getElementById("inicioQuestaoFarol");
        if(inicio){
            inicio.scrollIntoView({
                behavior: "smooth",
                block: "start"
            });
        }
    });

}

// ==========================
// CORRIGIR SIMULADO
// ==========================

function corrigirSimulado() {

    const resposta = document.querySelector(
        'input[name="resposta"]:checked'
    );

    if(!resposta){
        mostrarToast("Selecione uma alternativa.");
        return;
    }

    const q = questoesSimulado[indiceSimulado];
    const respostaMarcada = Number(resposta.value);
    const acertou = respostaMarcada === q.correta;

    revisaoSimuladoRespondidoFarol = {
        questao: q,
        respostaMarcada: respostaMarcada,
        numero: indiceSimulado + 1,
        total: questoesSimulado.length,
        feedbackHTML: ""
    };

    const respostaAluno =
        q.alternativas[respostaMarcada] ||
        "Resposta não registrada";

    const respostaCorreta =
        q.alternativas[q.correta] ||
        "Resposta correta não cadastrada";

    respostasSimulado.push({
        numero: indiceSimulado + 1,
        pergunta: q.pergunta,
        alternativas: q.alternativas,
        respostaMarcada: respostaMarcada,
        correta: q.correta,
        acertou: acertou,
        feedbackAcerto: q.feedbackAcerto || "",
        feedbackErro: q.feedbackErro || q.explicacao || "",
        dicaBanca: q.dicaBanca || ""
    });

    if(acertou){
        acertosSimulado++;
    }else{
        errosSimulado++;
    }

    const explicacao = acertou
        ? (
            q.feedbackAcerto ||
            "Resposta correta. Continue avançando no simulado."
        )
        : (
            q.feedbackErro ||
            q.explicacao ||
            "Sem explicação cadastrada."
        );

    document.getElementById("areaQuestao").innerHTML = `
        <div class="card tela-feedback-questao ${
            acertou
            ? "feedback-questao-acerto"
            : "feedback-questao-erro"
        }">

            <div style="display:flex;justify-content:flex-end;margin-bottom:4px;">
                <button
                    type="button"
                    class="btn-voltar-simulado-v48"
                    style="width:auto;padding:8px 12px;font-size:0.9rem;"
                    onclick="voltarDaQuestaoSimuladoFarol()">
                    ✕ Sair
                </button>
            </div>

            <div class="icone-feedback-questao">
                ${acertou ? "✅" : "❌"}
            </div>

            <span class="rotulo-feedback-questao">
                Simulado • Questão ${indiceSimulado + 1}
                de ${questoesSimulado.length}
            </span>

            <h2>
                ${acertou ? "Resposta correta!" : "Resposta incorreta"}
            </h2>

            <div class="resposta-aluno-simulado">
                <strong>Sua resposta</strong>
                <p>${respostaAluno}</p>
            </div>

            ${!acertou ? `
                <div class="bloco-resposta-correta">
                    <strong>✅ Resposta correta</strong>
                    <p>${respostaCorreta}</p>
                </div>
            ` : ""}

            <div class="bloco-feedback-explicacao">
                <strong>📘 Explicação</strong>
                <p>${explicacao}</p>
            </div>

            ${q.dicaBanca ? `
                <div class="bloco-feedback-dica">
                    <strong>💡 Dica da banca</strong>
                    <p>${q.dicaBanca}</p>
                </div>
            ` : ""}

            <div class="acoes-simulado-v48">
                <button
                    type="button"
                    class="btn-voltar-simulado-v48"
                    onclick="reverQuestaoSimuladoFarol()">
                    🔎 Rever questão
                </button>

                <button
                    type="button"
                    class="btn-proxima-feedback"
                    onclick="proximaQuestaoSimulado()">
                    ${
                        indiceSimulado + 1 >= questoesSimulado.length
                        ? "Ver resultado final ➜"
                        : "Próxima questão ➜"
                    }
                </button>
            </div>

        </div>
    `;

    if(revisaoSimuladoRespondidoFarol){
        revisaoSimuladoRespondidoFarol.feedbackHTML =
            document.getElementById("areaQuestao")?.innerHTML || "";
    }

    window.scrollTo({
        top: 0,
        left: 0,
        behavior: "smooth"
    });
}

// ==========================
// PRÓXIMA QUESTÃO SIMULADO
// ==========================

function proximaQuestaoSimulado() {

    revisaoSimuladoRespondidoFarol = null;

    indiceSimulado++;

    if (
        indiceSimulado
        >=
        questoesSimulado.length
    ) {

        finalizarSimulado();

        return;
    }

    mostrarQuestaoSimulado();

}

// ==========================
// FINALIZAR SIMULADO
// ==========================

function finalizarSimulado() {

    const total =
        acertosSimulado +
        errosSimulado;

    const percentual =
        total > 0
        ? (
            (acertosSimulado / total)
            * 100
        ).toFixed(1)
        : 0;

    const percentualNumero = Number(percentual);
    const hoje = dataHojeFarol();
    let pontosSimuladoHTML = "";

    if(adicionarPontosLuz(
        100,
        "Simulado finalizado",
        "simulado:" + tipoSimuladoAtual + ":" + hoje
    )){
        pontosSimuladoHTML += "⭐ 100 Pontos de Luz por finalizar o simulado<br>";
    }

    if(percentualNumero >= 90){
        if(adicionarPontosLuz(
            150,
            "Desempenho acima de 90% no simulado",
            "simulado90:" + tipoSimuladoAtual + ":" + hoje
        )){
            pontosSimuladoHTML += "🏆 150 Pontos de Luz por desempenho acima de 90%<br>";
        }
    }
    else if(percentualNumero >= 80){
        if(adicionarPontosLuz(
            100,
            "Desempenho acima de 80% no simulado",
            "simulado80:" + tipoSimuladoAtual + ":" + hoje
        )){
            pontosSimuladoHTML += "🥇 100 Pontos de Luz por desempenho acima de 80%<br>";
        }
    }

    registrarAtividadeDiaria("simulados", 1);

    const revisaoSimuladoHTML = respostasSimulado.map(item => {
        const respostaAluno =
            item.alternativas[item.respostaMarcada] ||
            "Resposta não registrada";

        const respostaCorreta =
            item.alternativas[item.correta] ||
            "Resposta correta não cadastrada";

        const explicacao =
            item.acertou
            ? (item.feedbackAcerto || "Resposta correta.")
            : (item.feedbackErro || "Sem explicação cadastrada.");

        return `
            <details class="item-correcao-simulado ${item.acertou ? "acertou" : "errou"}">
                <summary>
                    <span>${item.acertou ? "✅" : "❌"} Questão ${item.numero}</span>
                    <strong>${item.acertou ? "Acertou" : "Errou"}</strong>
                </summary>

                <div class="conteudo-correcao-simulado">
                    <p class="pergunta-correcao-simulado">${item.pergunta}</p>

                    <div class="resposta-aluno-simulado">
                        <strong>Sua resposta</strong>
                        <p>${respostaAluno}</p>
                    </div>

                    ${!item.acertou ? `
                        <div class="resposta-correta-simulado">
                            <strong>Resposta correta</strong>
                            <p>${respostaCorreta}</p>
                        </div>
                    ` : ""}

                    <div class="explicacao-correcao-simulado">
                        <strong>📘 Explicação</strong>
                        <p>${explicacao}</p>
                    </div>

                    ${item.dicaBanca ? `
                        <div class="dica-correcao-simulado">
                            <strong>💡 Dica da banca</strong>
                            <p>${item.dicaBanca}</p>
                        </div>
                    ` : ""}
                </div>
            </details>
        `;
    }).join("");

    document
        .getElementById(
            "areaQuestao"
        ).innerHTML = `

        <div class="card">

            <h2>
                🏁 SIMULADO FINALIZADO
            </h2>

            <br>

            <strong>
                Questões:
            </strong>

            ${total}

            <br><br>

            <strong>
                Acertos:
            </strong>

            ${acertosSimulado}

            <br><br>

            <strong>
                Erros:
            </strong>

            ${errosSimulado}

            <br><br>

            <strong>
                Aproveitamento:
            </strong>

            ${percentual}%

            ${pontosSimuladoHTML ? `
                <br><br>
                <div class="pontos-luz-box">
                    <strong>⭐ Pontos de Luz conquistados:</strong><br><br>
                    ${pontosSimuladoHTML}
                </div>
            ` : ""}

            <div class="correcao-final-simulado">
                <h3>📋 Correção das questões</h3>
                <p>Toque em cada questão para ver sua resposta, o gabarito e a explicação.</p>
                ${revisaoSimuladoHTML}
            </div>

            <br>

            <button onclick="
                modoSimulado = false;
                mostrarTela(
                    telaOrigemSimuladoFarol &&
                    telaOrigemSimuladoFarol !== 'resolverQuestao'
                    ? telaOrigemSimuladoFarol
                    : 'simulados'
                );
            ">
                ⬅ Voltar para a tela anterior
            </button>

        </div>

    `;

}

// ==========================
// SIMULADOS PERSONALIZADOS
// ==========================

function iniciarSimuladoPersonalizado(
    banco,
    quantidade,
    tipo
){

tipoSimuladoAtual = tipo || "personalizado";

    // Distribui a rodada entre os subtemas do conteúdo. Assim, simulados
    // personalizados não ficam concentrados em apenas um capítulo.
    questoesSimulado = selecionarQuestoesBalanceadasPorSubtopico(
        banco,
        Math.min(quantidade, banco.length)
    );

    modoSimulado = true;

    indiceSimulado = 0;

    acertosSimulado = 0;

    errosSimulado = 0;

    mostrarQuestaoSimulado();

}


