function limitarQuantidadeSimuladoFarol(banco, quantidadePadrao){

    const total = Array.isArray(banco) ? banco.length : 0;

    if(total === 0){
        return 0;
    }

    return Math.min(
        quantidadePadrao || 30,
        total
    );

}

