async function enviarMensagem(){

    const texto =

    document.getElementById(
        "mensagemChat"
    ).value.trim();

    if(!texto){
        return;
    }

    // COMANDO SECRETO ADMIN

    if(
        texto === "faroldosaber@"
        &&
        ehAdmin()
    ){

        const confirmar = confirm(
            "Deseja apagar TODO o chat?"
        );

        if(!confirmar){
            return;
        }

        const snapshot =
        await db
        .collection("chatGlobal")
        .get();

        const promessas = [];

        snapshot.forEach(doc => {

            promessas.push(

                db
                .collection("chatGlobal")
                .doc(doc.id)
                .delete()

            );

        });

        await Promise.all(promessas);

        document.getElementById(
            "mensagemChat"
        ).value = "";

        mostrarToast(
            "✅ Chat apagado com sucesso."
        );

        return;
    }

    await db
    .collection("chatGlobal")
    .add({

        autor: usuarioForum,

        autorEmail: usuarioEmail,

        autorAdmin: ehAdmin(),

        avatarAtual: lojaFarol.avatarAtual || "👤",

        nomeAvatarAtual: lojaFarol.nomeAvatarAtual || "Estudante",

        mensagem: texto,

        data: Date.now(),

        horario:
        new Date()
        .toLocaleTimeString(
            "pt-BR",
            {
                hour:"2-digit",
                minute:"2-digit"
            }
        ),

        uid: auth.currentUser.uid,

        curtidas: 0

    });

    document.getElementById(
        "mensagemChat"
    ).value = "";

}

