let timeoutDigitando;

function iniciarDigitando() {

    const campo =
    document.getElementById(
        "mensagemChat"
    );

    if(!campo){
        return;
    }

    campo.addEventListener(
        "input",
        async () => {

            if(!usuarioForum){
                return;
            }

            await db
            .collection("digitando")
            .doc(usuarioEmail)
            .set({

                nome: usuarioForum,
                timestamp: Date.now()

            });

            clearTimeout(
                timeoutDigitando
            );

            timeoutDigitando =
            setTimeout(
                async () => {

                    await db
                    .collection("digitando")
                    .doc(usuarioEmail)
                    .delete();

                },
                3000
            );

        }
    );

}

db.collection("digitando")
.onSnapshot(snapshot => {

    let texto = "";

    snapshot.forEach(doc => {

        const dados =
        doc.data();

        if(
            dados.nome !==
            usuarioForum
        ){

            texto =
            "✍️ " +
            dados.nome +
            " está digitando...";

        }

    });

    const area =
    document.getElementById(
        "digitandoInfo"
    );

    if(area){

        area.textContent =
        texto;

    }

});

