function nivelAtualLojaV65(){
    try{
        return Number(
            obterNivelLuzFarol(pontosLuz)?.nivel || 1
        );
    }catch(erro){
        return 1;
    }
}

function conquistaLojaLiberadaV65(id){
    if(!id){
        return true;
    }

    return Boolean(
        lojaFarol.conquistasDesbloqueadas &&
        lojaFarol.conquistasDesbloqueadas[id]
    );
}

function bloqueioItemLojaV65(item){
    if(!item){
        return {
            bloqueado: true,
            motivo: "Item não encontrado."
        };
    }

    if(item.nivelMinimo && nivelAtualLojaV65() < item.nivelMinimo){
        return {
            bloqueado: true,
            motivo: `Alcance o nível ${item.nivelMinimo} para liberar.`
        };
    }

    if(
        item.conquistaNecessaria &&
        !conquistaLojaLiberadaV65(item.conquistaNecessaria)
    ){
        return {
            bloqueado: true,
            motivo: "Desbloqueie a conquista exigida para liberar."
        };
    }

    if(item.id === "certificado_digital" && acertos < 100){
        return {
            bloqueado: true,
            motivo: `Faltam ${Math.max(100 - acertos, 0)} acertos para liberar.`
        };
    }

    return {
        bloqueado: false,
        motivo: ""
    };
}

function nomeRaridadeLojaV65(raridade){
    const nomes = {
        comum: "Comum",
        raro: "Raro",
        epico: "Épico",
        lendario: "Lendário"
    };

    return nomes[raridade] || "Comum";
}

function aplicarPersonalizacaoLojaV65(){
    const classes = [
        "moldura-maritima-v65",
        "moldura-dourada-v65",
        "efeito-brilho-v65",
        "efeito-ondas-v65"
    ];

    document.body.classList.remove(...classes);

    if(lojaFarol.molduraAtual){
        document.body.classList.add(lojaFarol.molduraAtual);
    }

    if(lojaFarol.efeitoAtual){
        document.body.classList.add(lojaFarol.efeitoAtual);
    }
}

function usarPersonalizacaoLojaV65(id){
    const item = obterRecompensaLoja(id);

    if(!item || !["moldura", "efeito"].includes(item.tipo)){
        mostrarToast("Personalização não encontrada.");
        return;
    }

    if(!recompensaComprada(id)){
        mostrarToast("Você ainda não adquiriu este item.");
        return;
    }

    if(item.tipo === "moldura"){
        lojaFarol.molduraAtual = item.classeAplicada;
        lojaFarol.molduraAtualId = item.id;
    }else{
        lojaFarol.efeitoAtual = item.classeAplicada;
        lojaFarol.efeitoAtualId = item.id;
    }

    aplicarPersonalizacaoLojaV65();
    salvarDados();
    atualizarDashboard();
    atualizarLojaFarol();
    salvarLojaFirebase();

    mostrarToast("✨ Personalização aplicada!");
}

function removerPersonalizacaoLojaV65(tipo){
    if(tipo === "moldura"){
        lojaFarol.molduraAtual = "";
        lojaFarol.molduraAtualId = "";
    }else{
        lojaFarol.efeitoAtual = "";
        lojaFarol.efeitoAtualId = "";
    }

    aplicarPersonalizacaoLojaV65();
    salvarDados();
    atualizarDashboard();
    atualizarLojaFarol();
    salvarLojaFirebase();

    mostrarToast("Personalização removida.");
}

window.usarPersonalizacaoLojaV65 =
    usarPersonalizacaoLojaV65;

window.removerPersonalizacaoLojaV65 =
    removerPersonalizacaoLojaV65;

function valorEhImagemAvatar(valor){
    return typeof valor === "string" && /\.(png|jpg|jpeg|webp|gif)$/i.test(valor);
}

function montarAvatarHTML(valor, nome, classe){
    const classeFinal = classe || "avatar-pequeno";
    const nomeSeguro = escaparHTML(nome || "Avatar");

    if(!valor){
        return `<span class="${classeFinal}">👤</span>`;
    }

    if(valorEhImagemAvatar(valor)){
        const srcSeguro = String(valor || "")
            .replaceAll('"', "%22")
            .replaceAll("'", "%27");

        return `
            <img
                src="${srcSeguro}"
                alt="${nomeSeguro}"
                class="${classeFinal}"
                loading="lazy">
        `;
    }

    return `<span class="${classeFinal}">${escaparHTML(valor)}</span>`;
}

function garantirSeletorAvatarV67(){
    let fundo = document.getElementById("seletorAvatarFarolV67");

    if(fundo){
        return fundo;
    }

    fundo = document.createElement("div");
    fundo.id = "seletorAvatarFarolV67";
    fundo.className = "seletor-avatar-farol-v67";
    fundo.setAttribute("aria-hidden", "true");

    fundo.innerHTML = `
        <div class="card-seletor-avatar-v67" role="dialog" aria-modal="true">
            <button
                type="button"
                class="fechar-seletor-avatar-v67"
                aria-label="Fechar">
                ×
            </button>

            <span class="tag-seletor-avatar-v67">ESCOLHA A VERSÃO</span>
            <h3>Qual avatar você deseja usar?</h3>
            <p>Toque em uma imagem. A opção escolhida ficará destacada.</p>

            <div class="opcoes-seletor-avatar-v67"></div>

            <div class="confirmacao-seletor-avatar-v67">
                <span>Selecionado:</span>
                <strong id="nomeSelecionadoAvatarV67">Nenhum</strong>
            </div>

            <button
                type="button"
                id="confirmarSeletorAvatarV67"
                class="confirmar-seletor-avatar-v67"
                disabled>
                Confirmar escolha
            </button>
        </div>
    `;

    document.body.appendChild(fundo);
    return fundo;
}

function obterVersaoAvatarItem(item){
    return new Promise(resolve => {
        const fundo = garantirSeletorAvatarV67();
        const opcoes = fundo.querySelector(".opcoes-seletor-avatar-v67");
        const confirmar = fundo.querySelector("#confirmarSeletorAvatarV67");
        const nomeSelecionado = fundo.querySelector("#nomeSelecionadoAvatarV67");
        const fechar = fundo.querySelector(".fechar-seletor-avatar-v67");

        const versoes = [
            {
                genero: "masculino",
                rotulo: "Masculino",
                avatar: item.avatarMasculino || item.avatar || "👤",
                nomeAvatar: item.nomeAvatarMasculino || item.nomeAvatar || item.nome || "Estudante"
            },
            {
                genero: "feminino",
                rotulo: "Feminino",
                avatar: item.avatarFeminino || item.avatar || "👤",
                nomeAvatar: item.nomeAvatarFeminino || item.nomeAvatar || item.nome || "Estudante"
            }
        ];

        let escolhida = null;
        const generoSalvo = localStorage.getItem("farol_genero_avatar") || "";

        opcoes.innerHTML = versoes.map(versao => `
            <button
                type="button"
                class="opcao-seletor-avatar-v67"
                data-genero="${versao.genero}">
                ${montarAvatarHTML(
                    versao.avatar,
                    versao.nomeAvatar,
                    "imagem-seletor-avatar-v67"
                )}
                <strong>${versao.rotulo}</strong>
                <small>${versao.nomeAvatar}</small>
                <span class="marca-selecao-avatar-v67">✓ Selecionado</span>
            </button>
        `).join("");

        const selecionar = genero => {
            escolhida = versoes.find(itemVersao => itemVersao.genero === genero) || null;

            opcoes.querySelectorAll(".opcao-seletor-avatar-v67").forEach(botao => {
                botao.classList.toggle(
                    "selecionada",
                    botao.dataset.genero === genero
                );
            });

            nomeSelecionado.textContent = escolhida
                ? `${escolhida.rotulo} — ${escolhida.nomeAvatar}`
                : "Nenhum";

            confirmar.disabled = !escolhida;
        };

        opcoes.querySelectorAll(".opcao-seletor-avatar-v67").forEach(botao => {
            botao.addEventListener("click", () => selecionar(botao.dataset.genero));
        });

        if(versoes.some(versao => versao.genero === generoSalvo)){
            selecionar(generoSalvo);
        }else{
            nomeSelecionado.textContent = "Nenhum";
            confirmar.disabled = true;
        }

        let finalizado = false;

        const encerrar = resultado => {
            if(finalizado){
                return;
            }

            finalizado = true;
            fundo.classList.remove("visivel");
            fundo.setAttribute("aria-hidden", "true");
            confirmar.onclick = null;
            fechar.onclick = null;
            resolve(resultado);
        };

        confirmar.onclick = () => {
            if(!escolhida){
                return;
            }

            localStorage.setItem("farol_genero_avatar", escolhida.genero);

            encerrar({
                avatar: escolhida.avatar,
                nomeAvatar: escolhida.nomeAvatar,
                genero: escolhida.genero,
                rotuloGenero: escolhida.rotulo
            });
        };

        fechar.onclick = () => encerrar(null);

        fundo.classList.add("visivel");
        fundo.setAttribute("aria-hidden", "false");
    });
}

function renderizarIconeLoja(item){
    if(item.tipo === "avatar"){
        const avatarMasculino =
            item.avatarMasculino ||
            item.avatar ||
            item.icone ||
            "👤";

        const avatarFeminino =
            item.avatarFeminino ||
            item.avatarMasculino ||
            item.avatar ||
            item.icone ||
            "👤";

        const nomeMasculino =
            item.nomeAvatarMasculino ||
            item.nomeAvatar ||
            item.nome ||
            "Avatar masculino";

        const nomeFeminino =
            item.nomeAvatarFeminino ||
            item.nomeAvatar ||
            item.nome ||
            "Avatar feminino";

        return `
            <div class="avatar-loja-dupla">
                <div class="avatar-opcao-loja">
                    ${montarAvatarHTML(
                        avatarMasculino,
                        nomeMasculino,
                        "avatar-loja-mini"
                    )}
                    <span>Masculino</span>
                </div>

                <div class="avatar-opcao-loja">
                    ${montarAvatarHTML(
                        avatarFeminino,
                        nomeFeminino,
                        "avatar-loja-mini"
                    )}
                    <span>Feminino</span>
                </div>
            </div>
        `;
    }

    return `<div class="icone-loja-emoji">${item.icone || "⭐"}</div>`;
}

function recompensaComprada(id){
    const item = obterRecompensaLoja(id);

    if(item && item.custo === 0){
        return true;
    }

    return !!(lojaFarol.comprados && lojaFarol.comprados[id]);
}

function obterRecompensaLoja(id){
    return recompensasLojaFarol.find(item => item.id === id);
}

function obterTituloAplicadoLoja(item){

    if(!item){
        return "";
    }

    if(item.tituloAplicado){
        return item.tituloAplicado;
    }

    return String(item.nome || "")
        .replace(/^Título\s+/i, "")
        .trim();

}

function gerarCodigoCertificado(){
    const ano = new Date().getFullYear();
    const numero = Math.floor(100000 + Math.random() * 900000);
    return `FAROL-${ano}-${numero}`;
}

async function comprarRecompensaLoja(id){

    const item = obterRecompensaLoja(id);

    if(!item){
        mostrarToast("Recompensa não encontrada.");
        return;
    }

    if(recompensaComprada(id)){
        mostrarToast("Você já possui esta recompensa.");
        return;
    }

    const bloqueioV65 = bloqueioItemLojaV65(item);

    if(bloqueioV65.bloqueado){
        mostrarToast(bloqueioV65.motivo);
        return;
    }

    let versaoAvatarPendenteV65 = null;

    if(item.tipo === "avatar"){
        versaoAvatarPendenteV65 = await obterVersaoAvatarItem(item);

        if(!versaoAvatarPendenteV65){
            mostrarToast("Escolha do avatar cancelada.");
            return;
        }
    }

    if(saldoPontosLuz < item.custo){
        mostrarToast("Você ainda não tem Pontos de Luz suficientes para esta troca.");
        return;
    }

    const confirmar = confirm(
        `Trocar ${item.custo} Pontos de Luz por ${item.nome}?`
    );

    if(!confirmar){
        return;
    }

    saldoPontosLuz -= item.custo;

    lojaFarol.comprados[id] = {
        nome: item.nome,
        custo: item.custo,
        data: Date.now()
    };

    if(item.tipo === "medalha"){
        lojaFarol.medalhaEstudanteAtivo = true;
    }

    if(item.tipo === "titulo"){
        lojaFarol.tituloAtual = obterTituloAplicadoLoja(item);
    }

    if(item.tipo === "avatar"){
        lojaFarol.avatarAtual =
            versaoAvatarPendenteV65.avatar;
        lojaFarol.nomeAvatarAtual =
            versaoAvatarPendenteV65.nomeAvatar;
    }

    if(item.tipo === "moldura"){
        lojaFarol.molduraAtual = item.classeAplicada;
        lojaFarol.molduraAtualId = item.id;
        aplicarPersonalizacaoLojaV65();
    }

    if(item.tipo === "efeito"){
        lojaFarol.efeitoAtual = item.classeAplicada;
        lojaFarol.efeitoAtualId = item.id;
        aplicarPersonalizacaoLojaV65();
    }

    if(item.tipo === "card"){
        lojaFarol.cardPremium = true;
    }

    if(item.tipo === "certificado"){
        lojaFarol.certificadoDigital = true;
        lojaFarol.codigoCertificado = lojaFarol.codigoCertificado || gerarCodigoCertificado();
        lojaFarol.dataCertificado = lojaFarol.dataCertificado || new Date().toLocaleDateString("pt-BR");

        setTimeout(() => {
            try{
                gerarCertificadoDigital();
            }catch(erro){
                console.log(erro);
            }
        }, 500);
    }

    salvarDados();
    atualizarDashboard();
    atualizarLojaFarol();
    salvarRankingFirebase();
    salvarLojaFirebase();

    mostrarToast(
        item.tipo === "avatar"
            ? `Avatar ${versaoAvatarPendenteV65.rotuloGenero} adquirido e aplicado!`
            : "Recompensa desbloqueada com sucesso!"
    );
}

async function usarAvatarLoja(id){

    const item = obterRecompensaLoja(id);

    if(!item || item.tipo !== "avatar"){
        return;
    }

    if(!recompensaComprada(id)){
        mostrarToast("Você ainda não desbloqueou este avatar.");
        return;
    }

    const versaoAvatar = await obterVersaoAvatarItem(item);

    if(!versaoAvatar){
        mostrarToast("Escolha do avatar cancelada.");
        return;
    }

    lojaFarol.avatarAtual = versaoAvatar.avatar;
    lojaFarol.nomeAvatarAtual = versaoAvatar.nomeAvatar;

    salvarDados();
    atualizarDashboard();
    atualizarLojaFarol();
    salvarRankingFirebase();
    salvarLojaFirebase();

    mostrarToast(
        `Avatar ${versaoAvatar.rotuloGenero} aplicado ao seu perfil.`
    );
}

function alterarVersaoAvatar(){
    localStorage.removeItem("farol_genero_avatar");
    mostrarToast("Escolha de versão liberada. Clique em usar avatar novamente.");
}

function recompensaEmUsoLoja(item){

    if(!item){
        return false;
    }

    if(item.tipo === "avatar"){
        return (
            lojaFarol.avatarAtual === item.avatarMasculino ||
            lojaFarol.avatarAtual === item.avatarFeminino ||
            lojaFarol.avatarAtual === item.avatar ||
            lojaFarol.nomeAvatarAtual === item.nomeAvatarMasculino ||
            lojaFarol.nomeAvatarAtual === item.nomeAvatarFeminino ||
            lojaFarol.nomeAvatarAtual === item.nomeAvatar
        );
    }

    if(item.tipo === "titulo"){
        return lojaFarol.tituloAtual === obterTituloAplicadoLoja(item);
    }

    if(item.tipo === "medalha"){
        return !!lojaFarol.medalhaEstudanteAtivo;
    }

    if(item.tipo === "card"){
        return !!lojaFarol.cardPremium;
    }

    if(item.tipo === "certificado"){
        return !!lojaFarol.certificadoDigital;
    }

    if(item.tipo === "moldura"){
        return lojaFarol.molduraAtualId === item.id;
    }

    if(item.tipo === "efeito"){
        return lojaFarol.efeitoAtualId === item.id;
    }

    return false;

}

function classeStatusLoja(item, comprada, semSaldo, bloqueadaCertificado){

    if(recompensaEmUsoLoja(item)){
        return "em-uso";
    }

    if(comprada){
        return "comprado";
    }

    if(semSaldo || bloqueadaCertificado){
        return "bloqueado";
    }

    return "disponivel";

}

function textoStatusLoja(item, comprada, semSaldo, bloqueadaCertificado){

    if(recompensaEmUsoLoja(item)){
        return "✅ Em uso";
    }

    if(comprada){
        return "✅ Desbloqueado";
    }

    if(bloqueadaCertificado){
        return "🔒 Requisito pendente";
    }

    if(semSaldo){
        return "🔒 Pontos insuficientes";
    }

    return "🛒 Disponível para troca";

}

function montarAcaoLoja(item, comprada, semSaldo, bloqueadaCertificado){

    const emUso =
        recompensaEmUsoLoja(item);

    if(emUso){
        return "";
    }

    if(comprada){

        if(item.tipo === "avatar"){
            return `
                <button onclick="usarAvatarLoja('${item.id}')">
                    Usar avatar
                </button>
            `;
        }

        if(item.tipo === "titulo"){
            return `
                <button onclick="usarTituloLoja('${item.id}')">
                    Usar título
                </button>
            `;
        }

        if(item.tipo === "certificado"){
            return `
                <button onclick="gerarCertificadoDigital()">
                    📜 Ver certificado
                </button>
            `;
        }

        if(item.tipo === "card"){
            return `
                <button onclick="compartilharProgresso()">
                    📤 Compartilhar card premium
                </button>
            `;
        }

        if(item.tipo === "moldura" || item.tipo === "efeito"){
            return `
                <button onclick="usarPersonalizacaoLojaV65('${item.id}')">
                    Usar ${item.tipo === "moldura" ? "moldura" : "efeito"}
                </button>
            `;
        }

        return "";

    }

    if(item.custo === 0 && item.tipo === "avatar"){
        return `
            <button onclick="usarAvatarLoja('${item.id}')">
                Usar avatar
            </button>
        `;
    }

    return `
        <button
            onclick="comprarRecompensaLoja('${item.id}')"
            ${semSaldo || bloqueadaCertificado ? "disabled" : ""}>

            ${
                semSaldo
                ? "Pontos insuficientes"
                : bloqueadaCertificado
                ? "Requisito pendente"
                : "Trocar por " + item.custo + " ⭐"
            }

        </button>
    `;

}


function usarTituloLoja(id){

    const item =
        recompensasLojaFarol.find(
            recompensa => recompensa.id === id
        );

    if(!item){
        mostrarToast("Título não encontrado.");
        return;
    }

    if(!recompensaComprada(id)){
        mostrarToast("Você ainda não desbloqueou este título.");
        return;
    }

    lojaFarol.tituloAtual =
        obterTituloAplicadoLoja(item);

    salvarDados();
    atualizarLojaFarol();
    atualizarDashboard();
    atualizarPainelEstudos();
    salvarRankingFirebase();
    salvarLojaFirebase();

    mostrarToast("🎖 Título ativado!");

}



