// Controla a navegação interna dos jogos.
// Ao abrir um jogo, esconde a tela anterior com os cartões e mostra somente
// o jogo escolhido. Ao voltar, restaura a Central de Jogos.
function definirModoJogoInternoFarol(ativo){

    const area = document.getElementById("areaJogoConstruaFarol");
    const card = area ? area.closest(".jogos-card") : null;

    if(!area || !card){
        return;
    }

    Array.from(card.children).forEach(elemento => {
        if(elemento === area){
            return;
        }

        if(ativo){
            if(!elemento.dataset.displayAntesJogoFarol){
                elemento.dataset.displayAntesJogoFarol =
                    elemento.style.display || "__vazio__";
            }
            elemento.style.display = "none";
        }else{
            const displayAnterior = elemento.dataset.displayAntesJogoFarol;

            if(displayAnterior){
                elemento.style.display =
                    displayAnterior === "__vazio__" ? "" : displayAnterior;
                delete elemento.dataset.displayAntesJogoFarol;
            }else{
                elemento.style.display = "";
            }
        }
    });

    card.classList.toggle("jogo-interno-ativo", ativo);
    area.classList.toggle("jogo-interno-visivel", ativo);

    if(ativo){
        window.scrollTo({ top: 0, left: 0, behavior: "smooth" });
    }
}

// Garante retorno dentro de qualquer jogo aberto na área dinâmica.
// Os jogos usam a mesma tela e substituem o conteúdo por JavaScript;
// por isso o botão precisa ser inserido sempre que a área for atualizada.
function garantirBotaoVoltarNosJogosFarol(){

    const area = document.getElementById("areaJogoConstruaFarol");

    if(!area || !area.innerHTML.trim()){
        definirModoJogoInternoFarol(false);
        return;
    }

    definirModoJogoInternoFarol(true);

    if(area.querySelector(".btn-voltar-jogos-automatico")){
        return;
    }

    const botao = document.createElement("button");
    botao.type = "button";
    botao.className = "btn-voltar btn-voltar-jogos-automatico";
    botao.textContent = "⬅ Voltar para Jogos";

    botao.addEventListener("click", function(){
        if(typeof pararTimerRelampago === "function"){
            pararTimerRelampago();
        }

        if(typeof pararPreviewMemoria === "function"){
            pararPreviewMemoria();
        }

        area.innerHTML = "";
        definirModoJogoInternoFarol(false);

        const telaJogos = document.getElementById("jogosFarol");
        if(telaJogos){
            telaJogos.scrollIntoView({
                behavior: "smooth",
                block: "start"
            });
        }else{
            window.scrollTo({ top: 0, left: 0, behavior: "smooth" });
        }
    });

    area.insertBefore(botao, area.firstChild);

    const espacamento = document.createElement("div");
    espacamento.className = "espacamento-voltar-automatico";
    espacamento.style.height = "12px";
    botao.insertAdjacentElement("afterend", espacamento);
}

function ativarObservadorVoltarJogosFarol(){

    const area = document.getElementById("areaJogoConstruaFarol");

    if(!area || area.dataset.observadorVoltarAtivo === "true"){
        return;
    }

    area.dataset.observadorVoltarAtivo = "true";

    const observador = new MutationObserver(function(){
        setTimeout(garantirBotaoVoltarNosJogosFarol, 0);
    });

    observador.observe(area, {
        childList: true,
        subtree: false
    });
}

if(document.readyState === "loading"){
    document.addEventListener("DOMContentLoaded", ativarObservadorVoltarJogosFarol);
}else{
    ativarObservadorVoltarJogosFarol();
}

function abrirTelaJogosFarol(){

    const area =
        document.getElementById("areaJogoConstruaFarol");

    if(area){
        area.innerHTML = "";
    }

    definirModoJogoInternoFarol(false);

}

function abrirJogoConstruaFarol(){

    const area =
        document.getElementById("areaJogoConstruaFarol");

    if(!area){
        return;
    }

    area.innerHTML = `
        <div class="painel-jogo-farol">
            <h3>🧱 Construa o Farol</h3>
            <p>
                Escolha uma disciplina. O jogo sorteia 5 questões e cada acerto constrói uma parte do farol.
            </p>

            <div class="grid-disciplinas-jogo">
                ${Object.keys(disciplinasJogoFarol).map(chave => `
                    <button onclick="iniciarConstruaFarol('${chave}')">
                        ${disciplinasJogoFarol[chave].nome}
                    </button>
                `).join("")}
            </div>
        </div>
    `;

    area.scrollIntoView({
        behavior: "smooth",
        block: "start"
    });

}

function embaralharArrayJogo(lista){

    const copia =
        [...lista];

    for(
        let i = copia.length - 1;
        i > 0;
        i--
    ){
        const j =
            Math.floor(
                Math.random() * (i + 1)
            );

        [copia[i], copia[j]] =
        [copia[j], copia[i]];
    }

    return copia;

}

function obterAssuntosJogoFarol(chaveDisciplina){

    if(chaveDisciplina === "todas"){

        const todos =
            Object.keys(disciplinasJogoFarol)
            .filter(chave => chave !== "todas")
            .flatMap(chave => disciplinasJogoFarol[chave].assuntos);

        return [...new Set(todos)];

    }

    return (
        disciplinasJogoFarol[chaveDisciplina] &&
        disciplinasJogoFarol[chaveDisciplina].assuntos
    ) || [];

}

function obterQuestoesJogoFarol(chaveDisciplina){

    const assuntos =
        obterAssuntosJogoFarol(chaveDisciplina);

    const questoes = [];

    assuntos.forEach(assunto => {

        const lista =
            bancoQuestoes[assunto];

        if(
            Array.isArray(lista) &&
            lista.length > 0
        ){
            lista.forEach((questao, indice) => {

                if(
                    questao &&
                    questao.pergunta &&
                    Array.isArray(questao.alternativas) &&
                    typeof questao.correta !== "undefined"
                ){
                    questoes.push({
                        ...questao,
                        assuntoJogo: assunto,
                        indiceOriginalJogo: indice,
                        disciplinaJogo: chaveDisciplina
                    });
                }

            });
        }

    });

    return embaralharArrayJogo(questoes);

}

function iniciarConstruaFarol(chaveDisciplina){

    const questoesDisponiveis =
        obterQuestoesJogoFarol(chaveDisciplina);

    if(questoesDisponiveis.length < 5){
        mostrarToast("Ainda não há questões suficientes para este jogo.");
        return;
    }

    jogoFarolQuestoes =
        questoesDisponiveis.slice(0, 5);

    jogoFarolIndice = 0;
    jogoFarolAcertos = 0;
    jogoFarolErros = 0;
    jogoFarolDisciplina = chaveDisciplina;
    jogoFarolRespondido = false;
    jogoFarolIdPartida = "jogo-farol-" + Date.now();

    mostrarQuestaoConstruaFarol();

}

function montarFarolVisualJogo(){

    const partesConstruidas =
        jogoFarolAcertos;

    return `
        <div class="farol-visual-jogo">
            ${partesFarolJogo.map((parte, indice) => `
                <div class="parte-farol-jogo ${indice < partesConstruidas ? "construida" : ""}">
                    <span>${indice < partesConstruidas ? "✅" : "⬜"}</span>
                    <strong>${parte}</strong>
                </div>
            `).join("")}
        </div>
    `;

}

function mostrarQuestaoConstruaFarol(){

    const area =
        document.getElementById("areaJogoConstruaFarol");

    if(!area){
        return;
    }

    const q =
        jogoFarolQuestoes[jogoFarolIndice];

    jogoFarolRespondido = false;

    const nomeDisciplina =
        disciplinasJogoFarol[jogoFarolDisciplina]
        ? disciplinasJogoFarol[jogoFarolDisciplina].nome
        : "🎯 Desafio";

    area.innerHTML = `
        <div class="painel-jogo-farol painel-jogo-ativo">

            <div class="cabecalho-jogo-farol">
                <div>
                    <h3>🧱 Construa o Farol</h3>
                    <p>${nomeDisciplina}</p>
                </div>

                <span>
                    Questão ${jogoFarolIndice + 1} de ${jogoFarolQuestoes.length}
                </span>
            </div>

            ${montarFarolVisualJogo()}

            <div class="placar-jogo-farol">
                <span>✅ Acertos: ${jogoFarolAcertos}</span>
                <span>❌ Erros: ${jogoFarolErros}</span>
                <span>⭐ ${jogoFarolAcertos * 10} Pontos</span>
            </div>

            <div class="questao-jogo-farol">

                ${q.texto ? `
                    <div class="texto-base jogo-texto-base">
                        ${q.texto}
                    </div>
                ` : ""}

                ${q.imagem ? `
                    <img src="${q.imagem}" class="imagem-questao">
                ` : ""}

                ${q.afirmacoes ? `
                    <div class="texto-base jogo-texto-base">
                        ${q.afirmacoes.map(af => `<p>${af}</p>`).join("")}
                    </div>
                ` : ""}

                <h3>${q.pergunta}</h3>

                <div class="alternativas-jogo-farol">
                    ${q.alternativas.map((alt, indice) => `
                        <button onclick="responderConstruaFarol(${indice})">
                            ${alt}
                        </button>
                    `).join("")}
                </div>

                <div id="feedbackJogoFarol"></div>

            </div>

        </div>
    `;

    area.scrollIntoView({
        behavior: "smooth",
        block: "start"
    });

}

