let memoriaPontos = 0;
let memoriaModoFarol = false;
let memoriaVez = "aluno";
let memoriaParesAluno = 0;
let memoriaParesFarol = 0;
let memoriaHistoricoFarol = {};
let memoriaPreviewAtivo = false;
let memoriaTempoPreview = 30;
