// ==========================================================
// FAROL V49 — AVANÇO AUTOMÁTICO DA ARENA
// ==========================================================

(function(){

    let timerAvancoTodosResponderamV49 = null;
    let rodadaAgendadaV49 = "";

    function jogadoresAtivosArenaV49(sala){
        const uids = Array.isArray(sala && sala.uids)
            ? sala.uids
            : [];

        const participantes =
            (sala && sala.participantes) || {};

        return uids.filter(uid => participantes[uid]);
    }

    function respostaEncerradaArenaV49(resposta){
        if(!resposta){
            return false;
        }

        return Boolean(resposta.acertou) ||
            Number(resposta.tentativas || 0) >= 2;
    }

    function situacaoRespostasArenaV49(sala){
        const jogadores =
            jogadoresAtivosArenaV49(sala);

        const respostas =
            (sala && sala.respostasRodada) || {};

        const concluidos = jogadores.filter(uid =>
            respostaEncerradaArenaV49(respostas[uid])
        );

        return {
            total: jogadores.length,
            concluidos: concluidos.length,
            todosResponderam:
                jogadores.length >= 2 &&
                concluidos.length === jogadores.length
        };
    }

    function cancelarAvancoArenaV49(){
        if(timerAvancoTodosResponderamV49){
            clearTimeout(timerAvancoTodosResponderamV49);
            timerAvancoTodosResponderamV49 = null;
        }

        rodadaAgendadaV49 = "";
    }

    function agendarAvancoArenaV49(sala){
        const usuario =
            typeof usuarioArenaAtualFarol === "function"
            ? usuarioArenaAtualFarol()
            : null;

        if(
            !sala ||
            !usuario ||
            sala.status !== "jogando" ||
            sala.criadoPor !== usuario.uid
        ){
            return;
        }

        const situacao =
            situacaoRespostasArenaV49(sala);

        if(!situacao.todosResponderam){
            cancelarAvancoArenaV49();
            return;
        }

        const rodada =
            `${sala.codigo}:${sala.questaoAtual || 0}:${sala.rodadaNumero || 0}`;

        if(rodadaAgendadaV49 === rodada){
            return;
        }

        cancelarAvancoArenaV49();
        rodadaAgendadaV49 = rodada;

        timerAvancoTodosResponderamV49 =
            setTimeout(() => {
                timerAvancoTodosResponderamV49 = null;

                if(
                    typeof window.avancarQuestaoArenaFarol === "function"
                ){
                    window.avancarQuestaoArenaFarol(true);
                }
            }, 2000);
    }

    const avancarArenaAntesV49 =
        window.avancarQuestaoArenaFarol;

    window.avancarQuestaoArenaFarol =
        async function(forcarPorRespostas = false){

            if(arenaAvancoEmAndamentoFarol){
                return;
            }

            const usuario = usuarioArenaAtualFarol();
            const sala = arenaSalaAtualFarol;

            if(
                !usuario ||
                !sala ||
                sala.criadoPor !== usuario.uid ||
                sala.status !== "jogando"
            ){
                return;
            }

            arenaAvancoEmAndamentoFarol = true;

            const ref = db
                .collection("arenasAoVivo")
                .doc(sala.codigo);

            try{

                await db.runTransaction(async transacao => {

                    const snapshot =
                        await transacao.get(ref);

                    if(!snapshot.exists){
                        return;
                    }

                    const dados =
                        snapshot.data() || {};

                    if(dados.status !== "jogando"){
                        return;
                    }

                    const fim =
                        calcularFimRodadaArenaFarol(dados);

                    const tempoEsgotado =
                        Date.now() + 500 >= fim;

                    const todosResponderam =
                        situacaoRespostasArenaV49(dados)
                            .todosResponderam;

                    if(
                        !tempoEsgotado &&
                        !(forcarPorRespostas && todosResponderam)
                    ){
                        return;
                    }

                    const atual =
                        Number(dados.questaoAtual || 0);

                    const total =
                        Array.isArray(dados.indices)
                        ? dados.indices.length
                        : 0;

                    if(atual + 1 >= total){

                        transacao.update(ref, {
                            status: "finalizada",
                            finalizadaEm:
                                firebase.firestore.FieldValue.serverTimestamp(),
                            atualizadoEm: Date.now()
                        });

                        return;
                    }

                    transacao.update(ref, {
                        questaoAtual: atual + 1,
                        rodadaNumero:
                            Number(dados.rodadaNumero || 0) + 1,
                        rodadaIniciadaEm:
                            firebase.firestore.FieldValue.serverTimestamp(),
                        respostasRodada: {},
                        atualizadoEm: Date.now()
                    });
                });

            }catch(erro){

                console.error(
                    "Erro ao avançar questão da Arena:",
                    erro
                );

            }finally{

                arenaAvancoEmAndamentoFarol = false;
                cancelarAvancoArenaV49();
            }
        };

    const renderizarPartidaAntesV49 =
        window.renderizarPartidaArenaFarol;

    if(typeof renderizarPartidaAntesV49 === "function"){

        window.renderizarPartidaArenaFarol = function(){

            const resultado =
                renderizarPartidaAntesV49.apply(
                    this,
                    arguments
                );

            const sala = arenaSalaAtualFarol;

            if(!sala || sala.status !== "jogando"){
                cancelarAvancoArenaV49();
                return resultado;
            }

            const situacao =
                situacaoRespostasArenaV49(sala);

            const feedback =
                document.getElementById(
                    "arenaFeedbackJogadorFarol"
                );

            if(feedback){

                let aviso =
                    document.getElementById(
                        "arenaProgressoRespostasV49"
                    );

                if(!aviso){
                    aviso = document.createElement("div");
                    aviso.id = "arenaProgressoRespostasV49";
                    aviso.className =
                        "arena-progresso-respostas-v49";
                    feedback.appendChild(aviso);
                }

                aviso.innerHTML =
                    situacao.todosResponderam
                    ? `
                        <strong>✅ Todos responderam.</strong>
                        <span>Próxima questão em 2 segundos...</span>
                    `
                    : `
                        <strong>
                            ${situacao.concluidos}/${situacao.total}
                            jogadores concluíram
                        </strong>
                        <span>
                            A próxima questão será liberada quando todos concluírem ou o tempo acabar.
                        </span>
                    `;
            }

            agendarAvancoArenaV49(sala);

            return resultado;
        };
    }

    const renderizarSalaAntesV49 =
        window.renderizarSalaArenaAoVivoFarol;

    if(typeof renderizarSalaAntesV49 === "function"){

        window.renderizarSalaArenaAoVivoFarol = function(){

            const resultado =
                renderizarSalaAntesV49.apply(
                    this,
                    arguments
                );

            if(
                !arenaSalaAtualFarol ||
                arenaSalaAtualFarol.status !== "jogando"
            ){
                cancelarAvancoArenaV49();
            }

            return resultado;
        };
    }

})();


// ==========================================================
// FAROL V51 — HISTÓRICO ADMINISTRATIVO DAS ARENAS
// ==========================================================

(function(){

    const historicosArenaSalvosV51 = new Set();

    function dataEmMilissegundosArenaV51(valor){
        if(!valor){
            return 0;
        }

        if(typeof valor.toMillis === "function"){
            return valor.toMillis();
        }

        if(typeof valor.toDate === "function"){
            return valor.toDate().getTime();
        }

        if(typeof valor.seconds === "number"){
            return valor.seconds * 1000;
        }

        const numero = Number(valor);
        return Number.isFinite(numero) ? numero : 0;
    }

    function classificacaoArenaV51(sala){
        return Object.values((sala && sala.participantes) || {})
            .map(participante => ({
                uid: String(participante.uid || ""),
                nome: String(
                    participante.nomeCompleto ||
                    participante.nome ||
                    "Aluno"
                ),
                email: String(participante.email || ""),
                pontos: Number(participante.pontos || 0),
                acertos: Number(participante.acertosArena || 0),
                erros: Number(participante.errosArena || 0),
                anfitriao:
                    String(participante.uid || "") ===
                    String(sala.criadoPor || "")
            }))
            .sort((a, b) =>
                b.pontos - a.pontos ||
                b.acertos - a.acertos ||
                a.erros - b.erros ||
                a.nome.localeCompare(b.nome, "pt-BR")
            )
            .map((participante, indice) => ({
                ...participante,
                posicao: indice + 1
            }));
    }

    async function salvarHistoricoArenaV51(sala){
        if(
            !sala ||
            !["finalizada", "encerrada", "cancelada"].includes(sala.status) ||
            typeof auth === "undefined" ||
            !auth.currentUser ||
            typeof db === "undefined"
        ){
            return;
        }

        const codigo = String(
            sala.codigo ||
            sala.id ||
            arenaSalaAtualCodigoFarol ||
            ""
        ).trim();

        if(
            !codigo ||
            String(sala.criadoPor || "") !== auth.currentUser.uid ||
            historicosArenaSalvosV51.has(codigo)
        ){
            return;
        }

        historicosArenaSalvosV51.add(codigo);

        const classificacao = classificacaoArenaV51(sala);
        const maiorPontuacao =
            classificacao.length
            ? classificacao[0].pontos
            : 0;

        const vencedores = classificacao
            .filter(item => item.pontos === maiorPontuacao)
            .map(item => ({
                uid: item.uid,
                nome: item.nome,
                email: item.email,
                pontos: item.pontos
            }));

        const inicioMs =
            dataEmMilissegundosArenaV51(sala.iniciadaEm);

        const fimMs =
            dataEmMilissegundosArenaV51(
                sala.finalizadaEm ||
                sala.encerradaEm ||
                sala.canceladaEm
            ) || Date.now();

        const participantes = classificacao.map(item => ({
            uid: item.uid,
            nome: item.nome,
            email: item.email,
            pontos: item.pontos,
            acertos: item.acertos,
            erros: item.erros,
            posicao: item.posicao,
            anfitriao: item.anfitriao
        }));

        try{
            await db
                .collection("historicoArenas")
                .doc(codigo)
                .set({
                    codigo: codigo,
                    tipo: "arena",
                    status: String(sala.status || ""),
                    motivoEncerramento:
                        String(sala.motivoEncerramento || ""),
                    criadoPor: String(sala.criadoPor || ""),
                    criadorNome: String(
                        (
                            sala.participantes &&
                            sala.participantes[sala.criadoPor] &&
                            (
                                sala.participantes[sala.criadoPor].nomeCompleto ||
                                sala.participantes[sala.criadoPor].nome
                            )
                        ) || ""
                    ),
                    concurso: String(sala.concurso || ""),
                    disciplina: String(sala.disciplina || ""),
                    topico: String(sala.topico || ""),
                    topicoNome: String(sala.topicoNome || ""),
                    quantidadeQuestoes:
                        Number(sala.quantidadeQuestoes || 0),
                    tempoPorQuestao:
                        Number(sala.tempoPorQuestao || 0),
                    totalParticipantes: participantes.length,
                    participantes: participantes,
                    participanteUids:
                        participantes.map(item => item.uid),
                    classificacao: classificacao,
                    vencedores: vencedores,
                    vencedorNome:
                        vencedores.length === 1
                        ? vencedores[0].nome
                        : vencedores.length > 1
                            ? "Empate"
                            : "",
                    iniciadaEm: sala.iniciadaEm || null,
                    finalizadaEm:
                        sala.finalizadaEm ||
                        sala.encerradaEm ||
                        sala.canceladaEm ||
                        firebase.firestore.FieldValue.serverTimestamp(),
                    duracaoMs:
                        inicioMs > 0
                        ? Math.max(0, fimMs - inicioMs)
                        : 0,
                    registradoEm:
                        firebase.firestore.FieldValue.serverTimestamp(),
                    atualizadoEm: Date.now()
                }, { merge: true });

        }catch(erro){
            historicosArenaSalvosV51.delete(codigo);

            console.error(
                "Erro ao salvar histórico da Arena:",
                erro
            );
        }
    }

    window.salvarHistoricoArenaFarol =
        salvarHistoricoArenaV51;

    const renderizarSalaAntesV51 =
        window.renderizarSalaArenaAoVivoFarol;

    if(typeof renderizarSalaAntesV51 === "function"){
        window.renderizarSalaArenaAoVivoFarol = function(){
            const resultado =
                renderizarSalaAntesV51.apply(this, arguments);

            const sala = arenaSalaAtualFarol;

            if(
                sala &&
                ["finalizada", "encerrada", "cancelada"]
                    .includes(sala.status)
            ){
                salvarHistoricoArenaV51(sala);
            }

            return resultado;
        };
    }

})();


// ==========================================================
// FAROL V56 — HISTÓRICO ADMINISTRATIVO DOS DUELOS
// ==========================================================

(function(){

    const historicosDuelosSalvosV56 = new Set();

    function ordenarParticipantesDueloV56(dados){
        return Object.entries((dados && dados.participantes) || {})
            .map(([uid, participante]) => ({
                uid: String(uid || ""),
                nome: String(
                    participante.nomeCompleto ||
                    participante.nome ||
                    "Aluno"
                ),
                email: String(participante.email || ""),
                acertos: Number(participante.acertos || 0),
                erros: Number(participante.erros || 0),
                finalizado: Boolean(participante.finalizado),
                entrouEm: participante.entrouEm || null,
                finalizadoEm: participante.finalizadoEm || null,
                respostas: Array.isArray(participante.respostas)
                    ? participante.respostas
                    : []
            }))
            .sort((a, b) =>
                b.acertos - a.acertos ||
                a.erros - b.erros ||
                a.nome.localeCompare(b.nome, "pt-BR")
            )
            .map((participante, indice) => ({
                ...participante,
                posicao: indice + 1
            }));
    }

    function dueloProntoParaHistoricoV56(dados){
        if(!dados){
            return false;
        }

        if(dados.cancelado === true){
            return true;
        }

        const participantes =
            Object.values(dados.participantes || {});

        return participantes.length >= 2 &&
            participantes.every(item => item && item.finalizado === true);
    }

    async function salvarHistoricoDueloV56(codigoOuDados){

        if(
            typeof auth === "undefined" ||
            !auth.currentUser ||
            typeof db === "undefined"
        ){
            return;
        }

        let dados = null;
        let codigo = "";

        if(typeof codigoOuDados === "string"){
            codigo = String(codigoOuDados).trim();

            const snapshot = await db
                .collection("duelos")
                .doc(codigo)
                .get();

            if(!snapshot.exists){
                return;
            }

            dados = snapshot.data() || {};
        }else{
            dados = codigoOuDados || {};
            codigo = String(dados.codigo || "").trim();
        }

        if(
            !codigo ||
            historicosDuelosSalvosV56.has(codigo) ||
            !dueloProntoParaHistoricoV56(dados)
        ){
            return;
        }

        const uidAtual = String(auth.currentUser.uid || "");
        const participanteDoDuelo =
            Array.isArray(dados.uids) &&
            dados.uids.includes(uidAtual);

        const criadorDoDuelo =
            String(dados.criadoPor || "") === uidAtual;

        if(!participanteDoDuelo && !criadorDoDuelo){
            return;
        }

        historicosDuelosSalvosV56.add(codigo);

        const participantes =
            ordenarParticipantesDueloV56(dados);

        const finalizados =
            participantes.filter(item => item.finalizado);

        const maiorPontuacao =
            finalizados.length
            ? Math.max(...finalizados.map(item => item.acertos))
            : 0;

        const vencedores =
            dados.cancelado
            ? []
            : finalizados
                .filter(item => item.acertos === maiorPontuacao)
                .map(item => ({
                    uid: item.uid,
                    nome: item.nome,
                    email: item.email,
                    acertos: item.acertos
                }));

        const finalizadoEm = Math.max(
            Number(dados.canceladoEm || 0),
            ...participantes.map(item =>
                Number(item.finalizadoEm || 0)
            ),
            Date.now()
        );

        try{
            await db
                .collection("historicoDuelos")
                .doc(codigo)
                .set({
                    codigo: codigo,
                    tipo: "duelo",
                    status:
                        dados.cancelado
                        ? "cancelado"
                        : "finalizado",
                    cancelado: Boolean(dados.cancelado),
                    canceladoPor:
                        String(dados.canceladoPor || ""),
                    criadoPor:
                        String(dados.criadoPor || ""),
                    criadoPorNome:
                        String(dados.criadoPorNome || ""),
                    disciplina:
                        String(
                            dados.nomeDisciplina ||
                            dados.disciplina ||
                            ""
                        ),
                    disciplinaChave:
                        String(dados.disciplina || ""),
                    assunto:
                        String(
                            dados.nomeAssunto ||
                            dados.assunto ||
                            ""
                        ),
                    assuntoChave:
                        String(dados.assunto || ""),
                    quantidade:
                        Number(
                            dados.quantidade ||
                            (dados.indices || []).length ||
                            0
                        ),
                    criadoEm:
                        dados.criadoEm || null,
                    finalizadoEm:
                        dados.canceladoEm ||
                        finalizadoEm,
                    totalParticipantes:
                        participantes.length,
                    participanteUids:
                        participantes.map(item => item.uid),
                    participantes:
                        participantes,
                    classificacao:
                        participantes,
                    vencedores:
                        vencedores,
                    vencedorNome:
                        dados.cancelado
                        ? "Duelo cancelado"
                        : vencedores.length === 1
                            ? vencedores[0].nome
                            : vencedores.length > 1
                                ? "Empate"
                                : "Não definido",
                    registradoEm:
                        firebase.firestore.FieldValue.serverTimestamp(),
                    atualizadoEm:
                        Date.now()
                }, { merge: true });

        }catch(erro){
            historicosDuelosSalvosV56.delete(codigo);

            console.error(
                "Erro ao salvar histórico do Duelo:",
                erro
            );
        }
    }

    window.salvarHistoricoDueloFarol =
        salvarHistoricoDueloV56;

    const mostrarResultadoAntesV56 =
        window.mostrarResultadoDuelo;

    if(typeof mostrarResultadoAntesV56 === "function"){
        window.mostrarResultadoDuelo = async function(codigo){
            const resultado =
                await mostrarResultadoAntesV56
                    .apply(this, arguments);

            try{
                await salvarHistoricoDueloV56(codigo);
            }catch(erro){
                console.error(
                    "Erro ao registrar resultado do Duelo:",
                    erro
                );
            }

            return resultado;
        };
    }

    const cancelarDueloAntesV56 =
        window.cancelarDuelo;

    if(typeof cancelarDueloAntesV56 === "function"){
        window.cancelarDuelo = async function(codigo){
            const resultado =
                await cancelarDueloAntesV56
                    .apply(this, arguments);

            try{
                await salvarHistoricoDueloV56(codigo);
            }catch(erro){
                console.error(
                    "Erro ao registrar cancelamento do Duelo:",
                    erro
                );
            }

            return resultado;
        };
    }

})();


